using System;

Random random = new Random();
bool playAgain = true;

while (playAgain)
{
    int secret = random.Next(1, 101);
    int attempts = 0;
    int guess = 0;
    bool correct = false;

    Console.WriteLine("\n=== Number Guessing Game ===" );
    Console.WriteLine("Guess the number between 1 and 100!");

    while (!correct)
    {
        Console.Write("Your guess: ");
        if (int.TryParse(Console.ReadLine() ?? "0", out guess))
        {
            if (guess < 1 || guess > 100)
            {
                Console.WriteLine("Please guess between 1 and 100.");
                continue;
            }

            attempts++;

            if (guess == secret)
            {
                Console.WriteLine($"Correct! You won in {attempts} attempts!");
                correct = true;
            }
            else if (guess < secret)
            {
                Console.WriteLine("Too low. Try higher.");
            }
            else
            {
                Console.WriteLine("Too high. Try lower.");
            }
        }
        else
        {
            Console.WriteLine("Please enter a valid number.");
        }
    }

    Console.Write("Play again? (yes/no): ");
    string response = Console.ReadLine()?.ToLower() ?? "no";
    playAgain = response == "yes" || response == "y";
}

Console.WriteLine("Thanks for playing!");
